CREATE TABLE movies
(
	movie_id INTEGER not null primary key,
	director_name TEXT, -- Example Values: `Ren Blood`   
	movie_title TEXT, -- Example Values: `('La Antena',)`, `('Elementary Particles',)`, `("It's Winter",)`  | Column Description: Name of the movie 
);

CREATE TABLE movies
(
	movie_id INTEGER not null primary key,
	movie_popularity INTEGER, -- Example Values: `(105,)`, `(23,)`, `(21,)`  | Column Description: Number of Mubi users who love this movie 
	director_name TEXT, -- Example Values: `Stanley Kubrick`   
);

CREATE TABLE lists
(
	list_followers INTEGER, -- Example Values: `(5,)`, `(1,)`, `(6,)`  | Column Description: Number of followers on the list 
	list_id INTEGER not null primary key,
	list_title TEXT, -- Example Values: `list`   
);

CREATE TABLE ratings
(
	foreign key (rating_id) references ratings(rating_id),
	foreign key (user_id) references ratings_users(user_id),
	rating_id INTEGER, --  
	movie_id INTEGER, -- Example Values: `(1066,)`, `(1067,)`, `(1068,)`  | Column Description: Movie ID related to the rating 
	foreign key (movie_id) references movies(movie_id),
);

